<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkspace} from '../../stores/workspace'
import {useIntegration} from '../../stores/integration'
import {useStationData} from '../../composables/useStationData'
import {useDetection} from '../../composables/useDetection'
import {allPages,errorText,localApi} from '../../services/local/api'
import {fields,localTime,phaseLabel,taskLabel,unitLabel,validRange,zoned} from '../../services/local/fields'
import {submissionDone,submissionKey} from '../../services/local/submission'
import type {Sample,Task} from '../../services/local/types'
import {csv,time} from '../../utils'
import Panel from '../../components/Panel.vue'
import ServiceState from '../../components/local/ServiceState.vue'
import LocalChart from '../../components/local/LocalChart.vue'
const route=useRoute(),router=useRouter(),workspace=useWorkspace(),service=useIntegration(),scope=useStationData(),{stationId,stations,datasets,models,station}=scope
const taskId=computed(()=>String(route.params.id??'')),detection=useDetection(taskId),{task,result,points,events}=detection
const datasetId=ref(''),modelKey=ref(''),name=ref('本站运行状态检测'),start=ref(''),end=ref(''),submitting=ref(false),error=ref(''),samples=ref<Sample[]>([]),sampleLoading=ref(false),sampleError=ref(''),parameter=ref(fields[0].field as string),samplePage=ref(1),selected=ref<string[]>([]),focusId=ref(''),history=ref<Task[]>([]),historyError=ref(''),historyLoading=ref(false),historyPage=ref(1)
const dataset=computed(()=>datasets.value.find(d=>d.id===datasetId.value)),model=computed(()=>models.value.find(m=>`${m.id}@${m.version}`===modelKey.value)),focus=computed(()=>events.value.find(e=>e.id===focusId.value)),visibleSamples=computed(()=>samples.value.slice((samplePage.value-1)*20,samplePage.value*20)),samplePages=computed(()=>Math.max(1,Math.ceil(samples.value.length/20))),historyPages=computed(()=>Math.max(1,Math.ceil(history.value.length/20)))
const rangeIssue=computed(()=>!start.value||!end.value?'请选择检测起止时间。':!validRange(zoned(start.value),zoned(end.value))?'检测开始时间必须早于结束时间。':dataset.value?.start&&dataset.value?.end&&(Date.parse(zoned(start.value))<Date.parse(dataset.value.start)||Date.parse(zoned(end.value))>Date.parse(dataset.value.end))?'检测范围不能超出所选数据集。':'')
const inputValid=computed(()=>!!workspace.context&&!!station.value&&dataset.value?.status==='ready'&&model.value?.status==='ready'&&!rangeIssue.value&&station.value.timezone==='Asia/Shanghai'&&model.value.stationId===stationId.value&&dataset.value.stationId===stationId.value)
const chartSeries=computed(()=>{const f=fields.find(f=>f.field===parameter.value)!;return [{name:f.label,unit:unitLabel(dataset.value?.columns.find(c=>c.field===f.field)?.unit??f.unit),color:'#2563eb',data:samples.value.map(s=>[s.timestamp,s.values[f.field]??null] as [string,number|null])}]})
const scoreSeries=computed(()=>[{name:'异常分数',unit:'分数',color:'#2563eb',data:points.value.map(p=>[p.timestamp,p.score] as [string,number])},{name:'阈值',unit:'分数',color:'#c2410c',data:points.value.map(p=>[p.timestamp,p.threshold] as [string,number])}])
let sampleController:AbortController|undefined,historyController:AbortController|undefined
watch(stations,rows=>{const requested=String(route.query.stationId??'');if(rows.some(s=>s.id===requested))stationId.value=requested})
watch(datasets,rows=>{datasetId.value=rows.find(d=>d.id===route.query.datasetId)?.id??rows.find(d=>d.id===datasetId.value)?.id??rows.find(d=>d.status==='ready')?.id??rows[0]?.id??''})
watch(models,rows=>{modelKey.value=rows.some(m=>`${m.id}@${m.version}`===modelKey.value)?modelKey.value:rows.find(m=>m.status==='ready')?`${rows.find(m=>m.status==='ready')!.id}@${rows.find(m=>m.status==='ready')!.version}`:''})
watch(datasetId,()=>{start.value=localTime(dataset.value?.start??null);end.value=localTime(dataset.value?.end??null);samples.value=[];sampleError.value='';sampleController?.abort();samplePage.value=1})
watch([start,end],()=>{sampleController?.abort();samples.value=[];sampleError.value='';sampleLoading.value=false})
watch(taskId,id=>{try{const saved=JSON.parse(localStorage.getItem(`shad-selected-events-${id}`)??'[]');selected.value=Array.isArray(saved)?saved.filter((v:unknown)=>typeof v==='string'):[]}catch{selected.value=[]}focusId.value=''},{immediate:true})
watch(selected,ids=>{if(taskId.value)try{localStorage.setItem(`shad-selected-events-${taskId.value}`,JSON.stringify(ids))}catch{/* Selection is a UI preference; task results remain on the backend. */}})
watch(events,rows=>{if(!result.value)return;selected.value=selected.value.filter(id=>rows.some(e=>e.id===id));if(!rows.some(e=>e.id===focusId.value))focusId.value=''})
async function loadHistory(){historyController?.abort();historyController=new AbortController();const c=historyController;history.value=[];historyError.value='';historyPage.value=1;if(!service.ready||!workspace.context)return;historyLoading.value=true
 try{const rows=await allPages(p=>localApi.detections(workspace.context!.segment.id,p,c.signal));if(!c.signal.aborted)history.value=rows}catch(e){if(!c.signal.aborted)historyError.value=errorText(e)}finally{if(!c.signal.aborted)historyLoading.value=false}}
watch([()=>service.ready,()=>service.revision,()=>workspace.context?.segment.id],loadHistory,{immediate:true})
watch(()=>task.value?.status,(s)=>{if(s==='success'||s==='failed')void loadHistory()})
async function loadSamples(){if(!dataset.value||!validRange(zoned(start.value),zoned(end.value)))return;sampleController?.abort();sampleController=new AbortController();const c=sampleController;sampleLoading.value=true;sampleError.value='';samples.value=[]
 try{const rows=await allPages(p=>localApi.samples(datasetId.value,zoned(start.value),zoned(end.value),fields.map(f=>f.field),p,c.signal));if(!c.signal.aborted){samples.value=rows;samplePage.value=1}}catch(e){if(!c.signal.aborted)sampleError.value=errorText(e)}finally{if(!c.signal.aborted)sampleLoading.value=false}}
async function submit(){if(!inputValid.value||submitting.value||!workspace.context||!model.value)return;error.value='';submitting.value=true;const context=workspace.context
 try{const body={name:name.value.trim(),context:{enterpriseId:context.enterprise.id,networkId:context.network.id,segmentId:context.segment.id,stationId:stationId.value},datasetId:datasetId.value,modelId:model.value.id,modelVersion:model.value.version,range:{start:zoned(start.value),end:zoned(end.value)}};const t=await localApi.createDetection(body,submissionKey('detection',body));submissionDone('detection');await router.push('/detections/'+encodeURIComponent(t.id));await loadHistory()}catch(e){error.value=errorText(e)}finally{submitting.value=false}}
async function retry(){if(!task.value||submitting.value)return;submitting.value=true;error.value='';try{const t=await localApi.retry(task.value.id,submissionKey('retry',task.value.id));submissionDone('retry');await router.push('/detections/'+encodeURIComponent(t.id));await loadHistory()}catch(e){error.value=errorText(e)}finally{submitting.value=false}}
function toggleAll(event:globalThis.Event){selected.value=(event.target as HTMLInputElement).checked?events.value.map(e=>e.id):[]}
function diagnose(){if(!task.value||!selected.value.length)return;router.push({path:'/diagnosis',query:{detectionId:task.value.id,eventIds:JSON.stringify(selected.value)}})}
function exportPoints(){csv([['时间','异常分数','阈值','点级超阈','持续性计数','健康度','确认告警'],...points.value.map(p=>[p.timestamp,p.score,p.threshold,String(p.alarm),p.criticality,p.health,String(p.confirmed)])],`${task.value?.id}-检测逐点结果.csv`)}
function exportEvents(){csv([['事件编号','开始','结束','持续小时','峰值分数','最大计数'],...events.value.map(e=>[e.id,e.start,e.end,e.hours,e.peak_score,e.max_criticality])],`${task.value?.id}-确认告警事件.csv`)}
function exportSamples(){csv([['时间',...fields.flatMap(f=>[f.label+'（'+unitLabel(dataset.value?.columns.find(c=>c.field===f.field)?.unit??f.unit)+'）',f.label+'质量'])],...samples.value.map(s=>[s.timestamp,...fields.flatMap(f=>[s.values[f.field]??'',s.quality[f.field]??'missing'])])],`${datasetId.value}-监测数据.csv`)}
onBeforeUnmount(()=>{sampleController?.abort();historyController?.abort()})
</script>
<template><div class="page-stack local-page"><div class="page-actions"><div><h2>数据监测</h2><p class="muted">本站数据 → 批次检测 → 综合状态异常事件。</p></div><RouterLink to="/networks">站点与数据管理</RouterLink></div><ServiceState><Panel title="本站检测配置"><p v-if="scope.error.value" class="error" role="alert">{{scope.error.value}} <button @click="scope.reload">重试</button></p><form @submit.prevent="submit"><fieldset :disabled="submitting||scope.loading.value||scope.loadingData.value" class="local-form-grid"><legend>选择实际数据与本站模型</legend><label>换热站<select v-model="stationId" aria-label="检测换热站" required><option value="">请选择换热站</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>数据集<select v-model="datasetId" aria-label="检测数据集" required><option value="">请选择数据集</option><option v-for="d in datasets" :key="d.id" :value="d.id">{{d.name}}{{d.status==='invalid'?'（校验未通过）':''}}</option></select></label><label>本站模型<select v-model="modelKey" aria-label="检测模型" required><option value="">请选择模型</option><option v-for="m in models" :key="m.id+m.version" :value="m.id+'@'+m.version" :disabled="m.status!=='ready'">{{m.name}} / {{m.version}}{{m.isDemo?'（示例模型）':''}}</option></select></label><label>任务名称<input v-model="name" required maxlength="80" /></label><label>开始时间（北京时间）<input v-model="start" type="datetime-local" aria-label="本机检测开始时间" required /></label><label>结束时间（北京时间）<input v-model="end" type="datetime-local" aria-label="本机检测结束时间" required /></label><div class="local-actions"><button class="secondary" type="button" :disabled="!dataset||!validRange(zoned(start),zoned(end))||sampleLoading" @click="loadSamples">{{sampleLoading?'读取中…':'读取监测数据'}}</button><button class="primary" :disabled="!inputValid||!name.trim()||!service.runtime?.capabilities.anomalyDetection">{{submitting?'提交中…':'创建本站检测'}}</button></div></fieldset></form><p v-if="!scope.loading.value&&!stations.length" class="empty">当前管段尚未关联换热站，请进入管网管理登记。</p><p v-if="station&&station.timezone!=='Asia/Shanghai'" class="error">当前表单仅支持北京时间站点，请先由后端核对本站时区。</p><p v-if="dataset&&rangeIssue" class="error" role="alert">{{rangeIssue}}</p><p v-if="model" class="muted">{{model.featureMode}} · {{model.scoreKind}} · {{model.adaptive?'工况自适应':'全局'}}阈值 · 持续性阈值 {{model.cThr}} · 模型参数只读</p><p class="muted">八个模型输入由数据集提供，不因图表选择而删减。短历史、缺口和质量问题由后端返回。</p><ul v-if="dataset?.issues.length"><li v-for="(i,j) in dataset.issues" :key="j">{{i.message}}</li></ul><p v-if="error" class="error" role="alert">{{error}}</p></Panel>
<Panel title="监测采样与趋势"><template #tools><label>曲线参数<select v-model="parameter" aria-label="本机图表参数"><option v-for="f in fields" :key="f.field" :value="f.field">{{f.label}}</option></select></label><button :disabled="!samples.length" @click="exportSamples">导出监测 CSV</button></template><p v-if="sampleError" class="error" role="alert">{{sampleError}}</p><p v-if="sampleLoading" role="status">正在完整读取所选范围的采样…</p><template v-else-if="samples.length"><LocalChart :series="chartSeries"/><div class="table-wrap"><table><thead><tr><th>采样时间</th><th>{{fields.find(f=>f.field===parameter)?.label}}</th><th>质量</th></tr></thead><tbody><tr v-for="s in visibleSamples" :key="s.timestamp"><td>{{time(s.timestamp)}}</td><td>{{s.values[parameter]??'缺失'}} {{unitLabel(dataset?.columns.find(c=>c.field===parameter)?.unit??'')}}</td><td>{{({valid:'有效',missing:'缺失',invalid:'无效'})[s.quality[parameter]??'missing']}}</td></tr></tbody></table></div><div class="pagination"><span>{{samples.length}} 条 · {{samplePage}} / {{samplePages}}</span><button :disabled="samplePage<=1" @click="samplePage--">上一页</button><button :disabled="samplePage>=samplePages" @click="samplePage++">下一页</button></div></template><p v-else class="empty">选择数据集和时间后，点击“读取监测数据”。没有数据时不显示模拟读数。</p></Panel>
<Panel v-if="taskId" title="检测任务与结果"><template #tools><button :disabled="detection.loading.value" @click="detection.reload">重新查询任务</button></template><p v-if="detection.error.value" class="error" role="alert">{{detection.error.value}} 查询失败不会改变任务状态。</p><p v-if="detection.loading.value" role="status">正在查询任务和完整结果…</p><template v-if="task"><div class="local-task-meta"><strong>{{task.name}}</strong><span class="badge orange">{{taskLabel[task.status]}}</span><span>{{task.id}}</span></div><p class="local-source">{{task.contextSnapshot.enterprise.name}} / {{task.contextSnapshot.network.name}} / {{task.contextSnapshot.segment.name}} / {{task.contextSnapshot.station.name}}</p><p>{{time(task.range.start)}} — {{time(task.range.end)}} · 模型 {{task.modelSnapshot.name}} / {{task.modelSnapshot.version}}</p><p v-if="task.status==='queued'||task.status==='running'" role="status">{{phaseLabel[task.phase]??task.phase}} · 等待后端返回实际结果，不模拟百分比。</p><p v-if="task.error" class="error" role="alert">{{task.error.message}} <button v-if="task.error.retryable" :disabled="submitting" @click="retry">创建重试任务</button></p><ul><li v-for="w in task.warnings" :key="w.code">{{w.message}}</li></ul><template v-if="result"><div class="local-summary"><span>有效点 {{result.summary.pointCount}}</span><span>超阈点 {{result.summary.alarmPointCount}}</span><span>确认告警 {{result.summary.eventCount}} 段</span><span>质量问题 {{result.summary.qualityIssueCount}}</span></div><LocalChart v-if="points.length" :series="scoreSeries" :events="events" :focus="focus" @select="focusId=$event"/><p class="muted">异常分数衡量综合运行偏离；健康度不是故障概率。告警事件不代表具体原因已确认。</p><div class="local-actions"><button :disabled="!points.length" @click="exportPoints">导出逐点 CSV</button><button :disabled="!events.length" @click="exportEvents">导出事件 CSV</button><button class="primary" :disabled="!selected.length" @click="diagnose">查看 {{selected.length}} 项事件与报告</button></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" aria-label="全选确认告警" :checked="!!events.length&&selected.length===events.length" :disabled="!events.length" @change="toggleAll"/></th><th>事件</th><th>起止时间</th><th>持续小时</th><th>峰值 / 计数</th><th>操作</th></tr></thead><tbody><tr v-for="e in events" :key="e.id" :class="{selected:focusId===e.id}"><td><input v-model="selected" type="checkbox" :value="e.id" :aria-label="'选择事件 '+e.id"/></td><td>{{e.title}}</td><td>{{time(e.start)}} — {{time(e.end)}}</td><td>{{e.hours}}</td><td>{{e.peak_score.toFixed(3)}} / {{e.max_criticality}}</td><td><button @click="focusId=e.id">定位区间</button></td></tr><tr v-if="!events.length"><td colspan="6" class="empty">检测成功，本次未形成确认告警事件。</td></tr></tbody></table></div></template></template></Panel>
<Panel title="本站检测历史"><template #tools><button :disabled="historyLoading" @click="loadHistory">刷新任务记录</button></template><p v-if="historyError" class="error" role="alert">{{historyError}}</p><p v-if="historyLoading" role="status">正在读取记录…</p><div class="table-wrap"><table><thead><tr><th>任务</th><th>站点</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in history.slice((historyPage-1)*20,historyPage*20)" :key="t.id"><td>{{t.name}}</td><td>{{t.contextSnapshot.station.name}}</td><td>{{taskLabel[t.status]}}</td><td>{{time(t.createdAt)}}</td><td><RouterLink :to="'/detections/'+encodeURIComponent(t.id)">查看任务</RouterLink></td></tr><tr v-if="!history.length&&!historyLoading"><td colspan="5" class="empty">当前管段暂无真实检测记录。</td></tr></tbody></table></div><div class="pagination"><span>{{history.length}} 条 · {{historyPage}} / {{historyPages}}</span><button :disabled="historyPage<=1" @click="historyPage--">上一页</button><button :disabled="historyPage>=historyPages" @click="historyPage++">下一页</button></div></Panel></ServiceState></div></template>
